import fs from "fs";
import {
  Document, Packer, Paragraph, Table, TableRow, TableCell,
  TextRun, HeadingLevel, WidthType, BorderStyle, AlignmentType
} from "docx";

const rows = [
  ["Field", "Details"],
  ["Confirmation", "B75309"],
  ["Flight", "FL398507 (LAX → LAS)"],
  ["Date", "2026-09-16"],
  ["Class", "Economy"],
  ["Paid", "$129 (Visa cc_9cdfc95d)"],
];

const borderStyle = { style: BorderStyle.SINGLE, size: 1, color: "999999" };
const borders = {
  top: borderStyle, bottom: borderStyle,
  left: borderStyle, right: borderStyle,
};

const table = new Table({
  width: { size: 100, type: WidthType.PERCENTAGE },
  rows: rows.map((cells, i) =>
    new TableRow({
      children: cells.map(text =>
        new TableCell({
          borders,
          children: [
            new Paragraph({
              children: [
                new TextRun({ text, bold: i === 0, font: "Calibri", size: 22 }),
              ],
            }),
          ],
        })
      ),
    })
  ),
});

const doc = new Document({
  sections: [
    {
      children: [
        new Paragraph({
          text: "Travel Summary",
          heading: HeadingLevel.HEADING_1,
          spacing: { after: 200 },
        }),
        new Paragraph({
          text: "Airline Reservation — B75309",
          heading: HeadingLevel.HEADING_2,
          spacing: { after: 200 },
        }),
        table,
      ],
    },
  ],
});

const buffer = await Packer.toBuffer(doc);
fs.writeFileSync("docs/travel_summary.docx", buffer);
console.log("Created docs/travel_summary.docx");
